import{_ as t,o,c as n,a2 as a}from"./chunks/framework.BDKIrnCI.js";const m=JSON.parse('{"title":"Documentation site","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/documentation-site.md"},"headers":[],"relativePath":"guides/documentation-site.md","filePath":"docs/documentation-site.md"}'),s={name:"guides/documentation-site.md"};function d(i,e,c,r,p,u){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="documentation-site" tabindex="-1">Documentation site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to &quot;Documentation site&quot;">​</a></h1><p>The VitePress site combines the hand-written guides in <code>docs/</code>, component READMEs, component-level guides, and generated API references. Plugin, tool, and action pages appear in separate navigation sections, and each component&#39;s navigation links to its reference.</p><h2 id="add-a-component-guide" tabindex="-1">Add a component guide <a class="header-anchor" href="#add-a-component-guide" aria-label="Permalink to &quot;Add a component guide&quot;">​</a></h2><p>Create Markdown files under the component&#39;s <code>docs/</code> folder. For example, a plugin can have an <code>index.md</code> plus additional pages such as <code>configuration.md</code>; tools and actions use the same layout. The site discovers each file and adds it under that component&#39;s navigation. Relative links are checked by <code>pnpm check</code>.</p><p>The component README serves as the overview when there is no custom <code>docs/index.md</code>. If a custom index exists, it becomes the component landing page and the README remains available as a separate <strong>README</strong> entry.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><p>The <strong>Reference</strong> section brings together documented exports from plugin and tool source, action inputs and outputs from each <code>action.yml</code>, and exported repository script helpers. TypeDoc follows the source folders discovered from package manifests; action contracts come directly from the action metadata. Add JSDoc beside exported code and add action documentation to <code>action.yml</code> so the site stays in sync without a second list of names or settings.</p><p>TypeDoc reads whole source trees, including implementation modules, so <code>excludeNotDocumented</code> keeps symbols without JSDoc out of the reference. It is a presentation filter, not a completeness check; the JSDoc lint enforces descriptions on exported TypeScript APIs.</p><p>Generated Pumpkin and WASI bindings can appear by name in public signatures, but their generated declarations are not included as reference pages. The docs pipeline generates the needed bindings before TypeDoc runs. Generated pages are build output and ignored by Git; edit source comments, action metadata, or <code>typedoc.json</code> instead.</p><p>VitePress adds an <strong>Edit this page on GitHub</strong> link to Markdown pages. Generated API pages link that action to the corresponding source file where TypeDoc can identify one.</p><h2 id="local-commands" tabindex="-1">Local commands <a class="header-anchor" href="#local-commands" aria-label="Permalink to &quot;Local commands&quot;">​</a></h2><p>Run <code>pnpm run docs</code> to generate bindings and the API reference, then build the complete static site. The two independent binding-generation steps run concurrently; TypeDoc and VitePress then run in order because the site reads the generated API pages. Use <code>pnpm run dev:docs</code> to generate the same inputs and start the VitePress development server, or <code>pnpm run docs:preview</code> to preview the last built site.</p><p>The pipeline can also be run in stages: <code>pnpm run docs:types</code> generates the binding declarations, <code>pnpm run docs:api</code> generates the TypeDoc reference after the bindings, and <code>pnpm run docs:site</code> builds the VitePress site from those generated pages. The binding steps can be run individually with <code>pnpm run docs:types:plugin-kit</code> or <code>pnpm run docs:types:update-check</code>. Plugin guest declarations can be generated with <code>pnpm run docs:types:plugins</code>. <code>pnpm run docs:build</code> is an alias for the complete production build.</p><p>The separate <code>.github/workflows/docs.yml</code> workflow checks docs on pull requests and publishes the site from pushes to <code>master</code> or <code>main</code>. It deploys a GitHub Pages artifact and mirrors the built files to the <code>gh-pages</code> branch. Configure the repository&#39;s Pages source to <strong>GitHub Actions</strong>.</p>',14)])])}const h=t(s,[["render",d]]);export{m as __pageData,h as default};
